def longest_run(xs):
    if not xs:
        return 0
    max_len = 1
    current_len = 1
    for i in range(1, len(xs)):
        if xs[i] > xs[i - 1]:
            current_len += 1
            if current_len > max_len:
                max_len = current_len
        else:
            current_len = 1
    return max_len
