def camel_to_snake(s):
    if not s:
        return s
    result = []
    for i, char in enumerate(s):
        if char.isupper():
            if i > 0 and (not s[i-1].isupper() or (i + 1 < len(s) and s[i+1].islower())):
                result.append('_')
            result.append(char.lower())
        else:
            result.append(char)
    return ''.join(result)
