def two_sum(xs, target):
    if not xs:
        return None
    seen = {}
    for j, val in enumerate(xs):
        complement = target - val
        if complement in seen:
            i = seen[complement]
            return (i, j)
        if val not in seen:
            seen[val] = j
    return None
```

