def parse_query(qs):
    if not qs:
        return {}

    result = {}
    # Remove leading '?' if present
    if qs.startswith('?'):
        qs = qs[1:]

    if not qs:
        return {}

    pairs = qs.split('&')
    for pair in pairs:
        if not pair:
            continue
        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            key = pair
            value = ''

        # URL decode key and value
        from urllib.parse import unquote
        key = unquote(key)
        value = unquote(value)

        if key in result:
            if isinstance(result[key], list):
                result[key].append(value)
            else:
                result[key] = [result[key], value]
        else:
            result[key] = value

    return result
