def word_wrap(text, width):
    if not text:
        return []
    words = text.split()
    if not words:
        return []
    lines = []
    current_line = []
    current_length = 0
    for word in words:
        word_len = len(word)
        if current_line:
            # Need space + word
            if current_length + 1 + word_len <= width:
                current_line.append(word)
                current_length += 1 + word_len
            else:
                lines.append(' '.join(current_line))
                current_line = [word]
                current_length = word_len
        else:
            # First word on line
            if word_len <= width:
                current_line.append(word)
                current_length = word_len
            else:
                # Word longer than width, put it on its own line
                lines.append(word)
                current_line = []
                current_length = 0
    if current_line:
        lines.append(' '.join(current_line))
    return lines
```

