def base_to_int(s, base):
    if not isinstance(s, str):
        raise ValueError("Input must be a string")
    if not isinstance(base, int) or base < 2 or base > 36:
        raise ValueError("Base must be an integer between 2 and 36")
    if s == "":
        raise ValueError("Empty string is not a valid number")

    valid_chars = "0123456789abcdefghijklmnopqrstuvwxyz"
    s_lower = s.lower()

    # Handle optional leading minus sign
    negative = False
    if s_lower.startswith("-"):
        negative = True
        s_lower = s_lower[1:]
    elif s_lower.startswith("+"):
        s_lower = s_lower[1:]

    if s_lower == "":
        raise ValueError("Empty string after sign is not a valid number")

    result = 0
    for char in s_lower:
        if char not in valid_chars:
            raise ValueError(f"Invalid digit '{char}' for base {base}")
        digit_value = valid_chars.index(char)
        if digit_value >= base:
            raise ValueError(f"Invalid digit '{char}' for base {base}")
        result = result * base + digit_value

    if negative:
        result = -result

    return result
